css:
/* Benefits split: a heading and a grid of icon, label items beside one photograph. The photo is on the
   right by default; a placement can flip it and set the number of columns in the page's CSS. */
[data-bz-node="bs-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="benefits-split"] .bz-block { padding-block: 0; }
[data-bz-section="benefits-split"] [data-bz-node="bs-split"] { align-items: center; }
[data-bz-section="benefits-split"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="benefits-split"] [data-bz-node="bs-items"] { display: grid; grid-template-columns: repeat(var(--bs-cols, 2), minmax(0, 1fr)); margin-top: 50px; row-gap: 40px; }
[data-bz-section="benefits-split"] [data-bz-node="bs-items"] > .bz-col { grid-column: auto; padding-inline: 10px; }
[data-bz-section="benefits-split"] .bz-figure { margin: 0; }
[data-bz-section="benefits-split"] [data-bz-node^="bs-icon"] .bz-figure { display: flex; justify-content: center; align-items: center; height: 60px; }
[data-bz-section="benefits-split"] [data-bz-node^="bs-icon"] img { width: auto; max-width: 100%; height: auto; border-radius: 0; }
[data-bz-section="benefits-split"] [data-bz-node="bs-photo"] img { display: block; width: 100%; height: auto; border-radius: 0; }
[data-bz-section="benefits-split"] [data-bz-node^="bs-label"] .bz-text p { margin: 16px auto 0; max-width: 220px; text-align: center; font: 400 0.8rem / 1.7 var(--font-body); color: #000; }
@media (max-width: 1100px) { [data-bz-section="benefits-split"] [data-bz-node="bs-split"] > [data-bz-node="bs-photo-col"] { order: -1; margin-bottom: 32px; } }
@media (max-width: 640px) { [data-bz-section="benefits-split"] [data-bz-node="bs-items"] { grid-template-columns: repeat(2, minmax(0, 1fr)); } [data-bz-section="benefits-split"] h2 { font-size: 1.5rem; } }
[data-bz-section="benefits-split"] [data-bz-node="bs-items"] .bz-container { padding-inline: 0; }
[data-bz-section="benefits-split"] [data-bz-node="bs-text-col"] .bz-container { padding-inline: 0; }
